function icon(string $name, string $class = 'icon'): string
{
    $paths = icon_paths()[$name] ?? icon_paths()['sparkles'];
    return '<svg class="' . e($class) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $paths . '</svg>';
}

/** Icons offered when an admin picks one for a product or feature. */
function icon_options(): array
{
    $names = ['sparkles', 'cart', 'gift', 'layers', 'package', 'link', 'ticket', 'banknote', 'truck', 'chart', 'trending-up', 'bot', 'percent', 'zap', 'target', 'smartphone', 'shield', 'globe', 'message', 'clock', 'star'];
    $options = [];
    foreach ($names as $name) {
        $options[$name] = ucwords(str_replace('-', ' ', $name));
    }
    return $options;
}
